n = len(grid)
path = []

def dfs(x, y, k):
    if k == 0:
        path.append(grid[x][y])
        return

    # If the current cell is greater than the previous cell, we should backtrack
    if grid[x][y] > grid[x - 1][y - 1]:
        return

    # Add the current cell to the path
    path.append(grid[x][y])

    # Directions
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for dx, dy in directions:
        nx, ny = x + dx, y + dy
        if 0 <= nx < n and 0 <= ny < n and grid[nx][ny] < grid[x][y]:
            dfs(nx, ny, k - 1)

for i in range(n):
    for j in range(n):
        dfs(i, j, k)

return path

